def main(inp):
    import openpyxl
    from openpyxl.utils import get_column_letter as g
    w1 = openpyxl.load_workbook('input.xlsx')
    w2 = openpyxl.load_workbook('output.xlsx')
    d = []
    for s in w1.sheetnames:
        if s not in w2.sheetnames: continue
        a, b = w1[s], w2[s]
        mr = max(a.max_row or 0, b.max_row or 0)
        mc = max(a.max_column or 0, b.max_column or 0)
        for r in range(1, mr + 1):
            for c in range(1, mc + 1):
                v1 = a.cell(r, c).value
                v2 = b.cell(r, c).value
                if v1 != v2:
                    d.append(f'{s}!{g(c)}{r}: {repr(v1)[:60]} -> {repr(v2)[:60]}')
    t = f'Cells directly modified: {len(d)}\n' + '\n'.join(d[:200])
    if len(d) > 200: t += f'\n... and {len(d)-200} more'
    return {'facts': {'regression_check': t}, 'files': {}}

